package vn.covie.outbox.application; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.*; import vn.covie.shared.outbox.*; import vn.covie.shared.time.AppClock;
@Service public class OutboxFailureService {private final OutboxEventRepository events;private final OutboxRetryPolicy retry;private final AppClock clock;public OutboxFailureService(OutboxEventRepository e,OutboxRetryPolicy r,AppClock c){events=e;retry=r;clock=c;} @Transactional(propagation=Propagation.REQUIRES_NEW) public void recordFailure(UUID id,Throwable failure){events.lockById(id).ifPresent(event->{if(event.getStatus()==OutboxEventStatus.PUBLISHED)return;int attempt=event.getAttempts()+1;Instant next=attempt>=retry.maxAttempts()?null:clock.now().plus(retry.delayForAttempt(attempt));event.markFailed(attempt,next,sanitize(failure));});}private static String sanitize(Throwable t){String message=t.getMessage()==null?"":t.getMessage().replaceAll("[\\r\\n]"," ");String value=t.getClass().getSimpleName()+(message.isBlank()?"":": "+message);return value.length()>1000?value.substring(0,1000):value;}}
